public class BlockEnergyCell extends BlockContainer{public BlockEnergyCell(){super(Material.IRON);setRegistryName(Reference.MOD_ID,"energy_cell");setHardness(3);setCreativeTab(net.minecraft.creativetab.CreativeTabs.REDSTONE);}public String getUnlocalizedName(){return "tile.nexus_tech.energy_cell";}public TileEntity createNewTileEntity(World w,int m){return new TileEntityEnergyCell();}}